import os
from typing import List, Dict, Optional

import boto3


def _normalize_locale(locale: str) -> str:
    return locale.replace("_", "-").lower().strip()


def list_or_select_voice_for_locale(locale: str, select_preferred: bool = True) -> List[Dict[str, str]] | Optional[Dict[str, str]]:
    """
    Lists Amazon Polly voices that match a target locale, or selects the first preferred voice.

    Args:
        locale: Target locale such as "en-US", "fr-FR", or "en_US".
        select_preferred: If True, return a single best match; otherwise return all matches.

    Returns:
        A list of matching voice dicts, or a single preferred voice dict, or None if no match.
    """
    polly = boto3.client("polly")
    target = _normalize_locale(locale)

    matched: List[Dict[str, str]] = []
    paginator = polly.get_paginator("describe_voices")

    for page in paginator.paginate():
        for voice in page.get("Voices", []):
            voice_locale = _normalize_locale(voice.get("LanguageCode", ""))
            language_name = voice.get("LanguageName", "").lower()

            if voice_locale == target or voice_locale.startswith(target) or target.startswith(voice_locale):
                matched.append(
                    {
                        "id": voice.get("Id", ""),
                        "name": voice.get("Name", ""),
                        "language_code": voice.get("LanguageCode", ""),
                        "language_name": voice.get("LanguageName", ""),
                        "gender": voice.get("Gender", ""),
                        "supported_engines": ",".join(voice.get("SupportedEngines", [])),
                    }
                )
            elif target.split("-")[0] == voice_locale.split("-")[0] or target.split("-")[0] in language_name:
                matched.append(
                    {
                        "id": voice.get("Id", ""),
                        "name": voice.get("Name", ""),
                        "language_code": voice.get("LanguageCode", ""),
                        "language_name": voice.get("LanguageName", ""),
                        "gender": voice.get("Gender", ""),
                        "supported_engines": ",".join(voice.get("SupportedEngines", [])),
                    }
                )

    if not select_preferred:
        return matched

    if not matched:
        return None

    preferred_genders = ["Female", "Male"]
    for gender in preferred_genders:
        for voice in matched:
            if voice.get("gender") == gender:
                return voice

    return matched[0]


if __name__ == "__main__":
    target_locale = os.getenv("TARGET_LOCALE", "en-US")
    preferred = list_or_select_voice_for_locale(target_locale, select_preferred=True)
    print(preferred if preferred is not None else "No matching voice found")
